// src/data/lexikon.js
//
// Fachlexikon ÖkoInvest: EINZIGE Quelle für alle Fachbegriffe unter
// /wissen/lexikon (Projektentwicklung Freiflächen-PV, Agri-PV, Solarcarports,
// Großspeicher, Projektbörse, Investment, virtuelles Kraftwerk, Reststrom-Pool
// und Energiegemeinschaften im DACH-Raum). Seite, Suche, A–Z-Leiste und
// DefinedTermSet-JSON-LD ziehen sich alles hieraus.
//
// Aufbau je Eintrag:
//   id        Anker-ID (nur a–z, 0–9, Bindestrich) – NIE ändern, wird verlinkt
//   begriff   angezeigter Fachbegriff
//   buchstabe optional: Einordnung in der A–Z-Leiste (z. B. "§ 6" unter K)
//   kurz      EIN zitierfähiger Satz (Definition, für AI-Overviews/LLMs)
//   text      Erklärung (2–4 Sätze, Orientierung Stand 2026)
//   kategorie eine aus KATEGORIEN
//   synonyme  optionale weitere Suchbegriffe
//   link      optional { href, label } auf passende ÖkoInvest-Seite/Rechner/Ratgeber
//   verwandt  optionale ids verwandter Begriffe
//
// Zahlen kommen, wo möglich, aus src/lib/invest/markt.js, damit Lexikon,
// Rechner und Seiten dieselben Werte nennen.
//
// Stand: September 2026. Gesetzes- und Förderangaben bei Änderungen hier pflegen.

import { PACHT, AGRI, CARPORT, PHASEN, PROVISION, KOMMUNE, ERLOESE, FREIFLAECHE, STROM, FINANZIERUNG } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const phase = (id) => PHASEN.find((p) => p.id === id);
const pct = (x, stellen = 0) => `${fmt(x * 100, stellen)} %`;
const spanne = (p) => `${fmt(p.preisProKwp.min)} bis ${fmt(p.preisProKwp.max)} €/kWp`;
const STROMSTEUER_REGEL = STROM.bestandteile.find((b) => b.id === "stromsteuer").ct;

export const LEXIKON_STAND = "2026-09-29";

export const KATEGORIEN = [
  { id: "planung", label: "Planung & Genehmigung" },
  { id: "flaeche", label: "Fläche & Landwirtschaft" },
  { id: "technik", label: "Technik & Netz" },
  { id: "markt", label: "Strommarkt & Vermarktung" },
  { id: "invest", label: "Investment & Transaktion" },
  { id: "gemeinschaft", label: "Gemeinschaften & DACH" },
];

export const BEGRIFFE = [
