// Statische Prüfung von Ratgeber-Artikeln (ohne Dev-Server).
// Aufruf: node mk_check.mjs <slug> [<slug> ...]
// Prüft: Laden/Syntax, Wortzahl (1.800–3.000), Tabellen >= 2, FAQ, Quellen 4–8 mit Stand,
// interne Links >= 8 und deren Gültigkeit (Routen, Ratgeber-Slugs, Lexikon-Anker), Pflichtfelder, Längen.
import { createJiti } from "file:///C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/node_modules/jiti/lib/jiti.mjs";
import fs from "node:fs";
import path from "node:path";

const ROOT = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web";
const jiti = createJiti(import.meta.url, { alias: { "@": ROOT + "/src" }, interopDefault: true, moduleCache: false, fsCache: false });

const lex = await jiti.import(ROOT + "/src/data/lexikon.js");
const lexIds = new Set((lex.LEXIKON || lex.BEGRIFFE || Object.values(lex).find((v) => Array.isArray(v) && v[0]?.begriff) || []).map((e) => e.id));
const artDir = ROOT + "/src/content/ratgeber";
const slugs = new Set(fs.readdirSync(artDir).filter((f) => f.endsWith(".js") && f !== "index.js" && !f.startsWith("_")).map((f) => f.replace(/\.js$/, "")));

// Routen aus src/app ableiten (ohne dynamische Segmente)
const routen = new Set(["/"]);
(function walk(d, pre) {
  for (const f of fs.readdirSync(d, { withFileTypes: true })) {
    if (!f.isDirectory()) continue;
    if (f.name.startsWith("(") || f.name === "api") { if (f.name.startsWith("(")) walk(path.join(d, f.name), pre); continue; }
    const r = pre + "/" + f.name;
    if (fs.existsSync(path.join(d, f.name, "page.js"))) routen.add(r);
    walk(path.join(d, f.name), r);
  }
})(ROOT + "/src/app", "");

function woerter(x) {
  if (typeof x === "string") return x.replace(/\[([^\]]+)\]\([^)]+\)/g, "$1").split(/\s+/).filter(Boolean).length;
  if (Array.isArray(x)) return x.reduce((s, y) => s + woerter(y), 0);
  if (x && typeof x === "object") return Object.entries(x).reduce((s, [k, v]) => (["id", "typ", "variant", "href", "url"].includes(k) ? s : s + woerter(v)), 0);
  return 0;
}
function links(x, out = []) {
  if (typeof x === "string") for (const m of x.matchAll(/\]\((\/[^)\s]*)\)/g)) out.push(m[1]);
  else if (Array.isArray(x)) x.forEach((y) => links(y, out));
  else if (x && typeof x === "object") for (const [k, v] of Object.entries(x)) { if (k === "href" && typeof v === "string" && v.startsWith("/")) out.push(v); else links(v, out); }
  return out;
}
function pruefeLink(l) {
  const [p, anker] = l.split("#");
  const pfad = p.split("?")[0].replace(/\/$/, "") || "/";
  if (pfad === "/wissen/lexikon") return !anker || lexIds.has(anker) ? null : `Lexikon-Anker fehlt: #${anker}`;
  if (pfad.startsWith("/ratgeber/")) return slugs.has(pfad.slice(10)) ? null : `Ratgeber fehlt: ${pfad}`;
  if (pfad.startsWith("/projektboerse/") && pfad !== "/projektboerse/anbieten") return `dynamische Börsen-Route vermeiden: ${pfad}`;
  return routen.has(pfad) ? null : `Route fehlt: ${pfad}`;
}

let fehlerGesamt = 0;
for (const slug of process.argv.slice(2)) {
  const out = [];
  let a;
  try { a = (await jiti.import(`${artDir}/${slug}.js`)).default ?? (await jiti.import(`${artDir}/${slug}.js`)); }
  catch (e) { console.log(`✗ ${slug}: LADEFEHLER ${e.message}`); fehlerGesamt++; continue; }
  const w = woerter([a.kurzFazit, a.abschnitte, a.faq]);
  const bl = (a.abschnitte || []).flatMap((s) => s.bloecke || []);
  const tab = bl.filter((b) => b.typ === "tabelle").length;
  const alleLinks = links([a.kurzFazit, a.abschnitte, a.faq]);
  const intern = [...new Set(alleLinks)];
  const kaputt = [...new Set(links(a).map(pruefeLink).filter(Boolean))];
  const pflicht = ["slug", "title", "seoTitle", "kurzTitel", "description", "excerpt", "hauptKeyword", "keywords", "veroeffentlicht", "aktualisiert", "kategorie", "bild", "bildAlt", "kurzFazit", "abschnitte", "faq", "passend", "quellen", "seitenCta", "cta"];
  const fehlt = pflicht.filter((k) => a[k] == null);
  const kat = ["Fläche & Pacht", "Agri-PV & Landwirtschaft", "Investieren & Projektbörse", "Recht & Genehmigung", "Strom, Markt & Gemeinschaft"];
  const bilder = ["solarpark-himmel", "solarpark-reihen", "solarpark-baeume", "freiflaeche-begehung", "investoren-vor-ort", "montage-freiflaeche", "planer-tablet", "pv-wind-abend", "module-sonne", "module-raster", "floating-pv", "floating-pv-montage", "gewerbedach", "dach-drohne", "techniker", "team-praesentation", "firmensitz", "speicher"].map((b) => `/img/${b}.jpg`);
  if (a.slug !== slug) out.push(`slug != Dateiname (${a.slug})`);
  if (fehlt.length) out.push("Pflichtfelder fehlen: " + fehlt.join(", "));
  if (w < 1800 || w > 3000) out.push(`Wortzahl ${w} (Soll 1.800–3.000)`);
  if (tab < 2) out.push(`nur ${tab} Tabelle(n)`);
  if (!a.faq || a.faq.length < 4) out.push(`FAQ ${a.faq?.length ?? 0} (< 4)`);
  const q = a.quellen || [];
  if (q.length < 4 || q.length > 8) out.push(`Quellen ${q.length} (Soll 4–8)`);
  if (q.some((x) => !x.stand || !/^https?:\/\//.test(x.url || ""))) out.push("Quelle ohne Stand/URL");
  if (intern.length < 8) out.push(`nur ${intern.length} verschiedene interne Links im Text (Soll ≥ 8)`);
  kaputt.forEach((k) => out.push("LINK: " + k));
